        engineeringData: { blockDesign: "Inline-4, Open-deck Aluminum block with cast iron cylinder liners. The N46 relies heavily on a complex Valvetronic system for throttle control, rather than a traditional throttle butterfly valve.", crankshaft: "Cast Iron, supported by 5 main bearings, equipped with twin balance shafts located in the oil pan.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "110A/150A Valeo/Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.5:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "143 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.59." }, cylinderHead: { combustionChamberVol: "Port injection specific pent-roof design.", intakePortFlow: "16-valve DOHC design. The head integrates the highly complex Valvetronic and Double-VANOS systems.", valveSizes: "Intake: 31.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable on BOTH sides. Driven by the notorious front-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Valvetronic Architecture & Chronic Oil Consumption. The N46 uses Valvetronic to eliminate pumping losses by using the intake valves to control airflow. However, the engine is critically flawed by its valve stem seals, which harden and fail prematurely, turning the engine into a massive oil burner. The timing chain guides are made of inferior plastic that shatters." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Chain-driven gerotor pump located in the oil pan.", thermostatOpening: "105°C Electronically mapped heat management.", oilCooler: "Integrated heat exchanger on the oil filter housing." }, fuelSystem: { systemType: "Bosch Multi-Point Port Injection.", maxPressure: "3.5 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "250 Nm", maxSafePowerStock: "170 hp (Tuning is highly discouraged and financially inefficient for naturally aspirated N-series engines).", maxSafeRPM: "6500 RPM", weakestLink: "Timing Chain Guides (Shatter), Valve Stem Seals (Massive Oil Consumption), Valvetronic Motor, Vacuum Pump, PCV Valve." }, electrical: { coils: "Individual Coil Pack system (4x Coil-on-Plug).", ecu: "Bosch MEV9.4.6." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic failures inherent to the N46 engine.", parts: [ { category: "Timing Chain Kit", brand: "Febi Bilstein / IWIS", note: "CRITICAL: Replace entire kit before 120k km to prevent engine death." }, { category: "Valve Stem Seal Kit", brand: "Elring / Victor Reinz", note: "CRITICAL: Cures the massive oil burning and blue smoke." }, { category: "Valvetronic Motor", brand: "VDO / Genuine BMW", note: "CRITICAL: Resolves limp mode and severe hesitation." }, { category: "Vacuum Pump Seal Kit", brand: "Elring", note: "CRITICAL: Stops oil leaking onto the hot exhaust." }, { category: "Valve Cover Assembly (with PCV)", brand: "Febi Bilstein / BMW", note: "CRITICAL: Replaces the torn integrated PCV membrane." }, { category: "VANOS Solenoids", brand: "Pierburg / Genuine BMW", note: "Cures rough idle and power loss." }, { category: "Coolant Expansion Tank", brand: "Mahle / Behr", note: "Proactively replace before it bursts." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "Prevents severe oil leaks down the block." } ] },
