            { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel filter to maintain airflow.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" },
            { interval: "30,000 km", timeLimit: "3 years", task: "Cabin Microfilter", details: "Replace the interior cabin filter.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "35 EUR" }
