            { interval: "100,000 km", timeLimit: "8 years", task: "Electric Water Pump & Thermostat", details: "CRITICAL: Proactively replace the electric water pump before it inevitably fails without warning, stranding you.", parts: ["Pierburg Pump", "Mahle Thermostat"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "450 EUR" },
            { interval: "80,000 km", timeLimit: "6 years", task: "Valve Cover Replacement", details: "CRITICAL: The integrated PCV valve tears, causing massive vacuum leaks. The plastic cover itself also warps and cracks.", parts: ["Valve Cover Assembly"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "450 EUR" }, 
            { interval: "As Needed", timeLimit: "Unlimited", task: "VANOS Solenoid Cleaning/Replacement", details: "Remove and ultrasonically clean or replace the two VANOS solenoids if the engine suffers from rough idling or hesitation.", parts: ["2x Pierburg Solenoids"], importance: "High", laborDifficulty: "Easy", estimatedCost: "180 EUR" },
            { interval: "120,000 km", timeLimit: "Unlimited", task: "DISA Valve Inspection/Rebuild", details: "Remove both DISA valves and check for loose flaps. Rebuild with aluminum kits to prevent engine damage.", parts: ["DISA Kits"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" },
            { interval: "60,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace spark plugs to prevent misfires.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "70 EUR" },
            { interval: "80,000 km", timeLimit: "6 years", task: "Ignition Coil Replacement", details: "Replace the coil packs to prevent sudden misfires under load.", parts: ["6x Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "180 EUR" }
