          preventiveAndSuspension: [ 
            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belts & Tensioner", details: "CRITICAL: Replace the drive belt and tensioner. A snapped belt on the N52 is highly dangerous due to front main seal ingestion risks.", parts: ["Continental Belt Kit"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "120 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Control Arm Bushings", details: "Replace front thrust arm bushings to cure severe steering shimmy under braking (a hallmark E83 issue).", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" }
          ],
