            { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Replace the primary drive belt and tensioner system.", parts: ["Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "100 EUR" }
