          { name: "Proactive Electric Water Pump", description: "Replacing the water pump and thermostat every 100k km with OEM Pierburg/VDO units before they fail.", benefit: "CRITICAL PREVENTATIVE MAINTENANCE. Prevents sudden, engine-warping overheating scenarios on the highway." },
          { name: "Bootmod3 / MHD Stage 1 Tune", description: "Flashing a conservative Stage 1 map via the OBD port.", benefit: "Safely optimizes the engine map for roughly 220hp and 350Nm, improving drivability while respecting the high-compression limits of the 'B' block." },
          { name: "Aluminum Mickey Mouse Flange", description: "Replacing the fragile plastic cooling hose flange with a precision-machined aluminum version.", benefit: "PERMANENT FIX. Prevents one of the most common and annoying sudden coolant blowout points on the N20 engine." },
          { name: "Aluminum Charge Pipe Upgrade", description: "Replacing the fragile factory plastic charge pipe with a mandrel-bent aluminum pipe.", benefit: "CRITICAL IF TUNED. The factory plastic pipe frequently explodes under increased boost pressure, leaving the car stranded." }
