        engineeringData: { blockDesign: "Inline-6, Magnesium-Aluminum composite block. The N52 features a magnesium outer shell for extreme weight reduction, with an aluminum inner core and cast iron cylinder liners. This makes it one of the lightest inline-6 engines ever built.", crankshaft: "Cast Iron, supported by 7 main bearings. Being an inline-6, it is inherently perfectly balanced, requiring no heavy balance shafts and resulting in incredibly smooth revving.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.7:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "143 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Port injection pent-roof design.", intakePortFlow: "24-valve DOHC design. The head integrates the highly complex Valvetronic (variable valve lift) and Double-VANOS (variable valve timing) systems.", valveSizes: "Intake: 33.0 mm / Exhaust: 30.5 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable on BOTH sides. Driven by a robust front-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Magnesium Block & 3-Stage DISA. The N52 uses the second generation of Valvetronic to eliminate the throttle body pumping losses, resulting in razor-sharp throttle response. The 30i represents the pinnacle of the naturally aspirated N52, utilizing the complex 3-stage intake manifold to provide a massive, flat torque curve." }, oilAndCooling: { oilSquirters: "Yes, under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump located in the oil pan.", thermostatOpening: "97°C - 105°C Electronically mapped thermostat.", oilCooler: "Integrated heat exchanger on the oil filter housing." }, fuelSystem: { systemType: "Bosch Multi-Point Port Injection.", maxPressure: "3.5 Bar (Fuel Rail).", injectors: "6x Bosch Solenoid Injectors. Exceptionally reliable." }, tuningLimits: { maxSafeTorqueStock: "350 Nm", maxSafePowerStock: "280 hp (Tuning NA N52 engines is financially inefficient. The complex magnesium block makes adding boost highly difficult).", maxSafeRPM: "7000 RPM", weakestLink: "Electric Water Pump (Sudden Failure), Oil Filter Housing Gasket (Belt Ingestion), Valve Cover (PCV Failure), DISA Valves." }, electrical: { coils: "Individual Coil Pack system (6x Coil-on-Plug).", ecu: "Siemens MSV90." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic cooling and oil leak failures inherent to the N52 engine.", parts: [ { category: "Electric Water Pump", brand: "Pierburg / VDO", note: "CRITICAL: Replace proactively every 100k km to prevent stranding." }, { category: "Thermostat", brand: "Mahle / Behr", note: "CRITICAL: Replace alongside the water pump." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "CRITICAL: Prevents oil dripping onto belt causing engine ingestion." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "CRITICAL: Must replace alongside OFHG to prevent snapping." }, { category: "Valve Cover Assembly", brand: "Elring / Genuine BMW", note: "CRITICAL: Replaces the torn integrated PCV membrane." }, { category: "VANOS Solenoids", brand: "Pierburg / Genuine BMW", note: "Cures rough idle and limp mode (Requires 2 units)." }, { category: "DISA Valves (Large & Small)", brand: "Genuine BMW", note: "Replace or rebuild with aluminum kit to restore torque." }, { category: "Spark Plugs", brand: "NGK ILZFR6D11", note: "Replace every 60k km for optimal performance." } ] },
