            { interval: "5 Years", timeLimit: "5 years", task: "Battery Replacement", details: "A weak battery causes cascading electronic glitches in the F25.", parts: ["90Ah AGM Battery"], importance: "High", laborDifficulty: "Easy", estimatedCost: "200 EUR" }
