        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with cast iron cylinder liners. The B47 is part of BMW's modular engine family (500cc per cylinder), featuring vast improvements in NVH (Noise, Vibration, Harshness) and reliability over the older N47.", crankshaft: "Forged Steel, supported by 5 main bearings, equipped with dual balance shafts.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "16-valve DOHC design. The intake tracts clog rapidly with EGR carbon.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the vastly improved rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Reliability Overhaul & NVH Improvement. The 190hp B47 is a massive leap forward. BMW entirely redesigned the acoustic casing and the timing chain mechanism, curing the fatal snapping flaw of the N47 while making the engine significantly quieter and smoother." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Integrated heavy-duty heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2000 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (The ZF 8HP transmission handles this perfectly).", maxSafePowerStock: "240 hp (The B47 aluminum block handles this power without issue).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), DPF (Clogs), Intake Manifold (Carbon Choke)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable)." } },
