        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with cast iron cylinder liners. The N57 block itself is highly efficient, smooth, and lightweight, but BMW's decision to move the timing chain to the rear of the engine created a massive maintenance hurdle.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, eliminating the need for balance shafts and resulting in an incredibly smooth diesel.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The intake tracts clog extremely rapidly with massive amounts of EGR carbon soot.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the notorious rear-mounted timing chain system.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Fleet Detune & Full Torque. This specific model is artificially restricted via software to exactly 211hp to meet specific corporate fleet tax thresholds in Europe (often Belgium). However, it retains the full 560Nm of torque. It is mechanically identical to the 258hp model, making it a spectacular sleeper when tuned." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Integrated heavy-duty heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "1800 Bar (Fuel Rail). Driven by the infamous Bosch CP4.2 HPFP.", injectors: "6x Bosch Solenoid Injectors. Highly sensitive to metal contamination." }, tuningLimits: { maxSafeTorqueStock: "700 Nm (The heavy-duty ZF 8HP70 transmission handles this perfectly).", maxSafePowerStock: "350 hp (The N57 aluminum block handles this power effortlessly).", maxSafeRPM: "4800 RPM", weakestLink: "Timing Chain (Snaps), CP4 Fuel Pump (Disintegrates), Vibration Damper (Tears), DPF (Clogs)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE7.3 (Highly tunable due to artificial restriction)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the catastrophic timing chain and fuel system failures inherent to the N57 diesel.", parts: [ { category: "Timing Chain Kit", brand: "Genuine BMW / IWIS", note: "CRITICAL: Must replace proactively. Requires transmission removal." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Replaces the tearing rubber crank pulley." }, { category: "EGR Valve", brand: "BorgWarner", note: "Proactively replace or clean if idle becomes rough." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "CRITICAL: Replace strictly every 30k km to protect the CP4 pump." }, { category: "Glow Plugs", brand: "Bosch / Beru", note: "Requires 6 units. Replace proactively to ensure DPF regeneration." }, { category: "Glow Plug Relay", brand: "Beru", note: "Often fails alongside glow plugs, preventing regens." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Replace to prevent accessory loss." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required for Walnut Blasting." } ] },
