        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with cast iron cylinder liners. The B47D20B is part of BMW's modular family, optimized for ultra-low NVH and Euro 6d emissions targets via MHEV integration.", crankshaft: "Forged Steel, supported by 5 main bearings, featuring integrated twin balance shafts to counteract 4-cylinder diesel vibrations.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "48V Integrated Starter-Generator (ISG).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "16-valve DOHC design. The intake tracts are prone to rapid carbon clogging from the EGR system.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a rear-mounted, reinforced timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Mild Hybrid Architecture & Extreme Detune. This B47 revision is engineered to work with a 48V lithium battery. The ISG can provide up to 11 hp of electric assist, allows for seamless engine restart under 15 km/h, and enables long-duration engine-off coasting. However, this specific model is mechanically a 190hp engine artificially detuned to 136hp for tax purposes, making it an incredible sleeper when tuned." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical/Electronically monitored.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,500 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors (latest Euro 6d spec)." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (Limited by the ZF 8HP50 capacity).", maxSafePowerStock: "240 hp (The B47 block and turbo easily handle this power level).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), SCR System (NOx Sensors), 48V Battery (Glitches)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch MD1 (Tunable, often requires bench unlock)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, SCR, and 48V failures inherent to the modern B47 MHEV diesel.", parts: [ { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point in Euro 6d exhaust systems." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2500-bar fuel system." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "AdBlue Metering Valve", brand: "Bosch", note: "Replace or clean if crystallization causes SCR faults." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Includes tensioner; critical due to ISG torque surges." } ] },
