        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with cast iron cylinder liners. The B47 is part of BMW's modular engine family, featuring vast improvements in NVH (Noise, Vibration, Harshness) and reliability over the older N47.", crankshaft: "Forged Steel, supported by 5 main bearings, equipped with dual balance shafts.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "16-valve DOHC design. The intake tracts clog rapidly with EGR carbon.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the vastly improved rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Sequential Twin-Turbo. The 25d is the pinnacle of the 4-cylinder diesel range. It utilizes a small, high-pressure turbo for instant low-end grunt, and seamlessly transitions via a complex vacuum bypass system to a large low-pressure turbo for massive top-end power, resulting in a flat 500Nm torque curve." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Integrated heavy-duty heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2500 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "550 Nm (The updated ZF 8HP50 transmission is the primary limiting factor).", maxSafePowerStock: "280 hp (The B47 aluminum block handles this power without issue).", maxSafeRPM: "4800 RPM", weakestLink: "Vacuum Hoses (Turbo Lag), EGR Cooler (Fire Risk), SCR System (Sensors/Pump Failure), DPF (Clogs)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, DPF, twin-turbo, and SCR failures inherent to the modern B47 25d diesel.", parts: [ { category: "Vacuum Hose Kit", brand: "Silicone Aftermarket", note: "CRITICAL: Replaces brittle lines to cure turbo lag." }, { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Must verify recall status to prevent fires." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point causing AdBlue countdowns." }, { category: "Turbo Pressure Converters", brand: "Pierburg", note: "Replace alongside vacuum lines for perfect boost." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Replaces the tearing rubber crank pulley." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2500-bar pump." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Replace proactively to ensure DPF regenerations." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing Walnut Blasting." } ] },
