        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with cast iron cylinder liners. The B57 is part of BMW's modular engine family, representing a monumental leap in NVH, smoothness, and ultimate reliability over the older N57.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, eliminating the need for balance shafts and resulting in a diesel engine that is as smooth as a petrol straight-six.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The intake tracts clog extremely rapidly with massive amounts of EGR carbon soot.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by a vastly improved, highly reliable rear-mounted timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Acoustic Perfection & Reliability Overhaul. The B57 is legendary for completely fixing the fatal flaws of the N57. The timing chain is massively reinforced, and the high-pressure fuel system is significantly more robust. Furthermore, extreme acoustic shielding makes the B57 virtually silent from inside the cabin, providing a V8-like surge of refined power." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Integrated heavy-duty heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2500 Bar (Fuel Rail). Highly robust revised high-pressure pump.", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The heavy-duty ZF 8HP75 transmission handles this perfectly).", maxSafePowerStock: "350 hp (The B57 aluminum block handles this power effortlessly).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), SCR System (Sensors/Pump Failure), DPF (Clogs), Intake Manifold (Carbon Choke)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, DPF, and SCR failures inherent to the modern B57 diesel.", parts: [ { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Must verify recall status to prevent fires." }, { category: "NOx Sensor (Front/Rear)", brand: "Genuine BMW", note: "Common failure point causing AdBlue countdowns." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Replaces the tearing rubber crank pulley." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the high-pressure pump." }, { category: "EGR Valve", brand: "BorgWarner", note: "Replace or clean if idling becomes rough." }, { category: "Glow Plugs", brand: "Bosch / Beru", note: "Requires 6 units. Replace proactively to ensure DPF regeneration." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing Walnut Blasting." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Replace to ensure accessory reliability." } ] },
