        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with cast iron cylinder liners. The B57D30S0 is the absolute pinnacle of BMW's diesel engineering, originally designed for the M550d.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, eliminating the need for balance shafts and resulting in an incredibly smooth diesel.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.0:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "24-valve DOHC design. The intake tracts are prone to rapid carbon clogging from the EGR system.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a rear-mounted, massively reinforced timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Alpina Hardware & Quad-Turbo Architecture. The LHD Facelift XD3 uniquely retains the mind-bending Quad-Turbo B57 (unlike the RHD Bi-Turbo MHEV). Alpina upgrades the intake tract, fits a much larger high-performance intercooler, customizes the sequential turbo boost mapping, and installs a bespoke lightweight Akrapovic exhaust system. The result is a staggering 394hp and 800Nm." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical/Electronically monitored.", oilCooler: "Upgraded heavy-duty heat exchanger by Alpina." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,500 Bar (Fuel Rail). Highly robust revised high-pressure pump.", injectors: "6x Bosch Piezo Injectors." }, tuningLimits: { maxSafeTorqueStock: "800 Nm (The Alpina Switch-Tronic ZF 8HP75 handles this perfectly).", maxSafePowerStock: "480 hp (The B57 Quad-Turbo handles this power effortlessly).", maxSafeRPM: "4800 RPM", weakestLink: "Vacuum Hoses (Turbo Lag), EGR Cooler (Fire Risk), SCR System (NOx Sensors)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable, customized by Alpina)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, SCR, and vacuum failures inherent to the modern B57 Quad-Turbo diesel.", parts: [ { category: "Vacuum Hose Kit", brand: "Silicone Aftermarket", note: "CRITICAL: Replaces brittle lines to cure turbo lag and limp mode." }, { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point in Euro 6d exhaust systems." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2500-bar fuel system." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Replace to ensure accessory reliability." } ] },
