        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B46 is the US-market SULEV variant of the B48. The closed-deck design provides extreme rigidity.", crankshaft: "Forged Steel, supported by 5 main bearings, equipped with dual balance shafts.", pistonSpeed: "16.8 m/s @ 6500 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a lower 10.2:1 compression ratio, heavily optimized for higher turbo boost without detonation.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Direct injection specific pent-roof design.", intakePortFlow: "16-valve DOHC design. Integrates Valvetronic and Double-VANOS.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.5 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable on BOTH sides.", lifterType: "Hydraulic bucket tappets.", specialFeature: "SULEV Emissions Hardware. The B46 features specialized catalytic converters and secondary air injection systems designed to meet America's incredibly strict Super Ultra-Low Emissions Vehicle standards, making it mechanically similar to the B48 but with more complex external plumbing." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the Heat Management Module.", oilCooler: "Integrated heat exchanger." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "350 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "500 Nm (The updated ZF 8HP50 transmission handles this perfectly).", maxSafePowerStock: "400 hp (The B46 low-compression block handles massive boost safely).", maxSafeRPM: "7000 RPM", weakestLink: "Plastic Coolant Lines (Snap), Heat Management Module (Fails internally), Plastic Charge Pipe (Explodes under boost)." }, electrical: { coils: "Individual Coil Pack system.", ecu: "Bosch MG1 (Highly tunable)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the cooling and vacuum failures inherent to the modern B46 petrol engine.", parts: [ { category: "Heat Management Module", brand: "Genuine BMW", note: "CRITICAL: Replace if engine runs too cold or overheats." }, { category: "Coolant Vent Line", brand: "VRSF / Genuine BMW", note: "CRITICAL: Proactively replace the brittle plastic line." }, { category: "Valve Cover Assembly", brand: "Genuine BMW / Elring", note: "Required when the integrated PCV membrane tears." }, { category: "Oil Filter Housing Base", brand: "Genuine BMW", note: "Replace if oil and coolant begin mixing." }, { category: "Spark Plugs", brand: "NGK SILZKGR8B8S", note: "Replace every 50k km to prevent under-load misfires." }, { category: "Ignition Coils", brand: "Eldor / Bosch", note: "Replace proactively to ensure perfect spark." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "Replaces the weak factory plastic unit." }, { category: "Serpentine Belt Kit", brand: "Continental", note: "Replace to ensure accessory reliability." } ] },
