        engineeringData: { blockDesign: "Inline-4, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B46 is the US-market SULEV variant of the B48. The closed-deck design provides extreme rigidity.", crankshaft: "Forged Steel, supported by 5 main bearings, equipped with dual balance shafts.", pistonSpeed: "16.8 m/s @ 6500 RPM.", alternator: "Integrated High-Voltage Motor/Generator.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a lower 10.2:1 compression ratio, heavily optimized for higher turbo boost without detonation.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Direct injection specific pent-roof design.", intakePortFlow: "16-valve DOHC design. Integrates Valvetronic and Double-VANOS.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.5 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Highly variable on BOTH sides.", lifterType: "Hydraulic bucket tappets.", specialFeature: "US PHEV Architecture & SULEV. The US-market 30e pairs a heavily restricted B46 petrol engine with a 109hp electric motor. The B46 features specialized catalytic converters and secondary air injection to meet America's incredibly strict SULEV standards. The 'XtraBoost' feature allows both powertrains to deliver a combined 292hp and 420Nm." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "Electronically mapped by the Heat Management Module.", oilCooler: "Integrated heat exchanger." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "350 Bar (Fuel Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The hybrid ZF 8HP75 transmission handles this perfectly).", maxSafePowerStock: "380 hp (Petrol block limit, B46 handles immense boost safely).", maxSafeRPM: "7000 RPM", weakestLink: "Plastic Coolant Lines (Snap), Heat Management Module (Fails internally), High-Voltage Battery (Degradation)." }, electrical: { coils: "Individual Coil Pack system.", ecu: "Bosch MG1 (Highly tunable)." } },
