          { partName: "Water Pump", category: "Cooling", oem: { brand: "BMW Genuine", code: "11518638026", approxPrice: "180 EUR" }, crossRef: { brand: "Pierburg", code: "7.07152.02.0", approxPrice: "110 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=11518638026", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=11518638026" }, note: "Mechanical pump driven by belt." },
          { partName: "Engine Air Filter", category: "Intake", oem: { brand: "BMW Genuine", code: "13718605164", approxPrice: "35 EUR" }, crossRef: { brand: "Mann Filter", code: "C 27 010", approxPrice: "18 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=13718605164", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=13718605164" }, note: "Protects the turbocharger." }
