        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with cast iron cylinder liners. The B57D30O2 is part of BMW's highly successful modular family. The closed-deck design provides extreme rigidity, optimized for ultra-low NVH and Euro 6e emissions targets.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, eliminating the need for balance shafts.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "48V Electric Motor integrated into Transmission (ISG).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "24-valve DOHC design. The intake tracts are prone to rapid carbon clogging from the EGR system.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a rear-mounted, massively reinforced timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Software Detune & Gen 4 MHEV Architecture. This 249hp Fleet Edition is a phenomenal sleeper. Mechanically identical to the 298hp model, it is artificially choked via software to meet extreme corporate tax brackets (often in Italy and Belgium). The G45 B57 abandons the belt-driven starter generator, integrating a highly powerful 48V electric motor directly into the ZF transmission bell housing. This provides instantaneous electric torque, masking the engine detune in the city." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical/Electronically monitored.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,500 Bar (Fuel Rail).", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The updated heavy-duty ZF 8HP75 transmission handles this perfectly).", maxSafePowerStock: "380 hp (The B57 block easily handles this power level).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), SCR System (NOx Sensors), ECU Encryption." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch MD1 (Heavily encrypted, requires FEMTO bench unlock)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, SCR, and cooling failures inherent to the modern B57 diesel.", parts: [ { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point in Euro 6e exhaust systems." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2500-bar fuel system." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "AdBlue Metering Valve", brand: "Bosch", note: "Replace or clean if crystallization causes SCR faults." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "Water Pump", brand: "Pierburg", note: "Replace proactively to prevent cooling loss." } ] },
